INSERT INTO "books" VALUES(757,NULL,'9781555977900','/books/OL27402438M','All That Man Is',NULL,'David Szalay',NULL,NULL,2017,NULL,'en',NULL,'Graywolf Press',368,NULL,'https://covers.openlibrary.org/b/id/8864776-L.jpg','Finalist for the 2016 Man Booker Prize
INSERT INTO "books" VALUES(758,NULL,'9781982122812','/books/OL57758364M','Flesh',NULL,'David Szalay',NULL,NULL,2025,NULL,'en',NULL,'Simon & Schuster',368,NULL,'https://covers.openlibrary.org/b/id/15110590-L.jpg','WINNER OF THE 2025 BOOKER PRIZE AND A NATIONAL BESTSELLER Finalist for the Kirkus Prize | Longlisted for the Carnegie Medal for Excellence From “the shrewdest writer on contemporary masculinity we have” (Esquire), a “captivating...hypnotic...virtuosic” (The Baffler) novel about a man whose life veers off course due to a series of unforeseen circumstances. Teenaged István lives with his mother in a quiet apartment complex in Hungary. Shy and new in town, he is a stranger to the social rituals practiced by his classmates and is soon isolated, drawn instead into a series of events that leave him forever a stranger to peers, his mother, and himself. In the years that follow, István is born along by the goodwill, or self-interest, of strangers, charting a rocky yet upward trajectory that lands him further from his childhood, and the defining events that abruptly ended it, than he could possibly have imagined. A collection of intimate moments over the course of decades, Flesh chronicles a man at odds with himself—estranged from and by the circumstances and demands of a life not entirely under his control and the roles that he is asked to play. Shadowed by the specter of past tragedy and the apathy of modernity, the tension between István and all that alienates him hurtles forward until sudden tragedy again throws life as he knows it in jeopardy. “Spare and detached on the page, lush in resonance beyond it” (NPR), Flesh traces the imperceptible but indelible contours of unresolved trauma and its aftermath amid the precarity and violence of an ever-globalizing Europe with incisive insight, unyielding pathos, and startling humanity.','read','2026-08-08','2026-08-09',2026,0,0,NULL,NULL,NULL,NULL,NULL,'2026-11-08 17:25:06','2026-11-08 17:25:06','2026-11-08','FD07972A-6A2B-4C64-911D-902A9973B534');
INSERT INTO "books" VALUES(759,NULL,'9781982122744','/books/OL35971585M','Turbulence',NULL,'David Szalay',NULL,NULL,2021,NULL,'en',NULL,'Simon and Schuster',160,NULL,NULL,'*A New York Times Book Review Editors’ Choice*
INSERT INTO "books" VALUES(760,NULL,'9780811228343','/books/OL28057076M','Michael Kohlhaas',NULL,'Heinrich von Kleist',NULL,NULL,2020,NULL,'en',NULL,'New Directions Publishing Corporation',112,NULL,'https://covers.openlibrary.org/b/id/12560614-L.jpg','Michael Kohlhaas has been wronged. First his finest horses were unfairly confiscated and mistreated. And things keep going worse--his servants have been beaten, his wife killed, and the lawsuits he pursues are stymied--but Kohlhaas, determined to find justice at all costs, tirelessly persists. Standing up against the bureaucratic machine of the empire, Kohlhaas becomes an indomitable figure that you can''t help rooting for from start to finish.
INSERT INTO "books" VALUES(761,NULL,'9781400031009','/books/OL19873716M','Any Human Heart',NULL,'William Boyd',NULL,NULL,2004,NULL,'en',NULL,'National Geographic Books',512,NULL,'https://covers.openlibrary.org/b/id/6636180-L.jpg','William Boyd’s masterful new novel tells, in a series of intimate journals, the story of Logan Mountstuart—writer, lover, art dealer, spy—as he makes his often precarious way through the twentieth century.','read','2026-08-17','2026-08-26',2026,0,0,NULL,NULL,NULL,NULL,NULL,'2026-11-08 17:25:06','2026-11-08 17:25:06','2026-11-08','A420E430-8ED2-4A57-932C-DA7B0495D9E7');
INSERT INTO "books" VALUES(762,NULL,'9780679731726','/books/OL62379580M','The Remains of the Day',NULL,'Kazuo Ishiguro',NULL,NULL,1990,NULL,'en',NULL,'National Geographic Books',256,NULL,'https://covers.openlibrary.org/b/id/15241848-L.jpg','BOOKER PRIZE WINNER • From the winner of the Nobel Prize in Literature, here is “an intricate and dazzling novel” (The New York Times) about the perfect butler and his fading, insular world in post-World War II England. 
INSERT INTO "books" VALUES(763,NULL,'9780593803417',NULL,'The Traveler',NULL,'Andrea Wulf',NULL,NULL,2026,NULL,'en',NULL,'Random House Digital Inc.',NULL,NULL,NULL,'THE NEW YORK TIMES BOOK REVIEW EDITORS'' CHOICE • SHORTLISTED FOR THE BAILLIE GIFFORD PRIZE • Step into the life and times of George Forster, the eighteenth-century naturalist who sailed the world and made waves with his revolutionary ideas about humanity and freedom—from the bestselling author of The Invention of Nature. "[A] thrilling biography-cum-adventure story." —Hampton Sides, author of The Wide Wide Sea “Enthralling. Superb. The Traveler is hypnotically successful and wonderfully restores George Forster as a major historical figure.” —Richard Holmes, author of The Age of Wonder From an early age, it was clear that George Forster possessed a brilliant mind. At just ten years old, he became a botanist when he accompanied his irascible father, Reinhold, on a wild expedition to Russia. By the time he was twelve, they had moved to London and the young boy soon became the breadwinner by publishing translations of the most popular travel accounts of the day. Then, in 1772, at the age of seventeen, George Forster joined Cook’s second voyage, the most daring expedition of the time. The HMS Resolution set sail with orders to find what was then the hypothetical southern continent of Antarctica, stopping at the islands of the South Pacific— including New Zealand, Vanuatu, Tonga, Tahiti, and Easter Island—along the way. The Resolution car­ried the ambitions of the most powerful empire in the world, but Forster brought an understanding that was far ahead of his day. A gifted observer, linguist, artist, and writer, he studied the diverse cultures of the world without prejudice and was one of the first Europeans to talk about universal human rights. Recognized on his return as one of Europe’s brightest minds, Forster used his fame to advocate for freedom and human rights and wrote against empire, white supremacy, and slavery. He admired strong, educated women, even accepting his wife’s independence—and her love affairs. Driven by his passion for equality, Forster would eventually be pulled into the vortex of the French Revolution and live in Paris during the Reign of Terror. Throughout it all, he held close the radical belief that our common humanity is far greater than what sets us apart. The Traveler recounts the remarkable life of this deeply curious and exceptional man who, though largely forgotten by history, truly belonged to the future.','read','2026-10-04','2026-10-11',2026,0,0,NULL,NULL,NULL,NULL,NULL,'2026-11-08 17:25:06','2026-11-08 17:25:06','2026-11-08','3A32E44A-7A9B-4A69-8063-E3030483FA43');
INSERT INTO "books" VALUES(764,NULL,'9780393068948','/books/OL23697465M','The Relentless Revolution: A History of Capitalism',NULL,'Joyce Appleby',NULL,NULL,2010,NULL,'en',NULL,'W.W. Norton & Co',494,NULL,'https://covers.openlibrary.org/b/id/6308080-L.jpg','With its deep roots and global scope, the capitalist system provides the framework for our lives--a framework of constant change, sometimes measured and predictable, sometimes drastic and out of control. Yet what is now ubiquitous was not always so. Capitalism took shape centuries ago, starting with a handful of isolated changes in farming, trade, and manufacturing, clustered in early-modern England. Astute observers began to notice these changes and consider their effects. Those in power began to harness these new practices to the state, enhancing both. A system generating wealth, power, and new ideas arose to reshape societies in a constant surge of change. Approaching capitalism as a culture, as important for its ideas and values as for its inventions and systems, award-winning historian Joyce Appleby gives us a fascinating introduction to this most potent creation of mankind from its origins to the present.--From publisher description.','read','2026-10-12','2026-10-19',2026,0,0,NULL,NULL,NULL,NULL,NULL,'2026-11-08 17:25:06','2026-11-08 17:25:06','2026-11-08','F9A38B7B-E74D-46D5-832B-785D88EE4C22');
INSERT INTO "books" VALUES(765,NULL,'9780226837475','/books/OL57515902M','Bacteria to AI: Human Futures with Our Nonhuman Symbionts',NULL,'N. Katherine Hayles',NULL,NULL,2025,NULL,'en',NULL,'The University of Chicago Press',287,NULL,NULL,'"Humans are driving the planet toward catastrophe, and yet humans are the only species capable of taking positive actions on a global scale to prevent collapse. For N. Katherine Hayles, human hubris and the anthropocentrism that underlies it is one of the main drivers of our current planetary crises. So, if we are to take action to save the planet, we urgently need to re-think basic assumptions about agency, decision-making, control, and our relations to nonhuman and artificial cognizers. In Bacteria to AI, Hayles develops an integrated cognitive framework (ICF) that includes humans, nonhuman lifeforms, and some computational media, including artificial intelligence. Bacteria to AI analyzes how the first-order emergences of physical phenomena, multicellularity, and technics are now interacting together to create second-order emergences that greatly accelerate technical developments. The book explores these entanglements through case studies ranging from gene editing to autopoiesis and Gaia theory, bacteria and xenobots to artificial intelligence. Spanning evolutionary biology, artificial intelligence, and contemporary literature, Bacteria to AI recognizes the risks of contemporary technologies but insists a positive way forward, with ICF at its core, is possible for us and for the more than human world"--','read','2026-10-20','2026-10-26',2026,0,0,NULL,NULL,NULL,NULL,NULL,'2026-11-08 17:25:06','2026-11-08 17:25:06','2026-11-08','D11BB8E8-5FA9-43D6-AAC7-078A9A18A868');
INSERT INTO "books" VALUES(766,NULL,'9780374620059','/books/OL62543880M','The Proof in the Code: How a Truth Machine Is Transforming Math and AI',NULL,'Kevin Hartnett',NULL,NULL,2026,NULL,'en',NULL,'Quanta Books',288,NULL,'https://covers.openlibrary.org/b/id/15254302-L.jpg','"The inside story of Lean, a computer program that answers the age-old question: How do you know if something is true?"--','read','2026-10-27','2026-11-04',2026,0,0,NULL,NULL,NULL,NULL,NULL,'2026-11-08 17:25:06','2026-11-08 17:25:06','2026-11-08','C8F3CBC2-B092-4BA9-B8FC-EE36068B46F3');
